document.addEventListener("DOMContentLoaded",function(){if(typeof AOS!="undefined"){var t=window.matchMedia("(max-width: 1100px), (prefers-reduced-motion: reduce), (update: slow)").matches||!!(navigator.connection&&navigator.connection.saveData);document.querySelectorAll(".hero [data-aos]").forEach(function(e){e.classList.add("aos-animate")}),AOS.init({once:!0,offset:24,duration:t?0:380,delay:0,easing:"ease-out-cubic",mirror:!1,disable:t,throttleDelay:32,debounceDelay:24}),t||window.setTimeout(function(){document.querySelectorAll("[data-aos]:not(.aos-animate)").forEach(function(e){var a=e.getBoundingClientRect();a.top<window.innerHeight*.92&&e.classList.add("aos-animate")})},900)}});
